children:
body,
      html {
        margin: 0;
      }
      .shell__container {
        height: 100vh;
        width: 100vw;
        position: fixed;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        background-color: #f4f4f4;
      }
      .shell__spinner {
        box-sizing: border-box;
        -webkit-animation: 1s linear infinite rotation;
        animation: 1s linear infinite rotation;
        border-radius: 100%;
        margin: 0 auto;
        border: 0.1875rem solid rgba(32, 145, 235, 0.25);
        height: 2rem;
        width: 2rem;
      }
      .shell__spinner::before {
        box-sizing: border-box;
        border: 0.1875rem solid transparent;
        height: 2rem;
        left: -0.1875rem;
        top: -0.1875rem;
        width: 2rem;
        border-right-color: #2091eb;
        border-top-color: #2091eb;
        border-radius: 100%;
        content: '';
        display: block;
        position: absolute;
      }
      @keyframes rotation {
        from {
          transform: rotate(0);
        }
        to {
          transform: rotate(359deg);
        }
      }
